    out = [row[:] for row in grid]
    h = len(grid)
    if not h:
        return out
    w = len(grid[0])
    pairs = []
    # Paired horizontal markers at the top or bottom edge specify the rails.
    for r in (0, h - 1):
        for c in range(w - 1):
            if grid[r][c] == 2 and grid[r][c + 1] == 2:
                pairs.append((r, c, c + 1))
